/**
 * Long-form province content — เนื้อหาเชิงลึกเฉพาะจังหวัด (12,000+ คำเป้าหมาย)
 *
 * GENERATED-FORMAT MODULE — one record per province, written from the province's
 * content brief (docs/seo/province-content-briefs/<slug>.md) and the hand-authored
 * unique angle (docs/seo/province-unique-angles.json). Content rules enforced by
 * shared/provinceLongform.test.ts:
 *  - word count floor (3,200) with a 12,000-word target
 *  - every section must name the province (no template drift)
 *  - no invented savings/payback numbers — only sourced PVGIS figures
 *
 * Honesty: PVGIS figures quoted here are climate normals from
 * shared/provinceEnergyData.ts (PVGIS v5.3, PVGIS-ERA5, 2005–2023) — not a
 * savings promise. Local facts marked ต้องตรวจสอบ must be verified before
 * publishing; unverified claims are withheld, never invented.
 */

export type LongformSection = {
  h2: string;
  /** Paragraphs and H3 subsections in reading order. */
  blocks: Array<
    | { type: "p"; text: string }
    | { type: "h3"; text: string }
    | { type: "list"; items: string[] }
  >;
};

export type ProvinceLongform = {
  slug: string;
  nameTh: string;
  intro: string[];
  sections: LongformSection[];
  faq: Array<{ q: string; a: string }>;
  /** Pulled into the page's closing CTA. */
  cta: string;
};

const p = (text: string) => ({ type: "p" as const, text });
const h3 = (text: string) => ({ type: "h3" as const, text });
const list = (items: string[]) => ({ type: "list" as const, items });

