export const provinceLongform: Record<string, ProvinceLongform> = {
  bangkok,
};

/** Thai-aware word count (Intl.Segmenter) — the metric the tests enforce. */
export function countWords(text: string): number {
  const segmenter = new Intl.Segmenter("th", { granularity: "word" });
  // Array.from instead of for..of: the repo's tsc target disallows iterating
  // Segments directly (TS2802); runtime behaviour is identical.
  const segments = Array.from(
    segmenter.segment(text) as unknown as Iterable<{ isWordLike?: boolean }>,
  );
  let count = 0;
  for (const segment of segments) {
    if (segment.isWordLike) count++;
  }
  return count;
}

export function longformWordCount(entry: ProvinceLongform): number {
  const parts: string[] = [...entry.intro, entry.cta];
  for (const section of entry.sections) {
    parts.push(section.h2);
    for (const block of section.blocks) {
      if (block.type === "list") parts.push(...block.items);
      else parts.push(block.text);
    }
  }
  for (const item of entry.faq) {
    parts.push(item.q, item.a);
  }
  return countWords(parts.join(" "));
}
